def _q(category, points, text, answer, identity, entity, name, source, claim, *, year=None,
       event=None, archetype='career_clues', mechanic='direct_recall', tone='nostalgia',
       aliases=(), visual=None, note=None, template=None):
    """Only editorially checked rows enter this explicit pilot manifest."""
    source_name, source_url = SOURCES[source]
    return {'category': category, 'difficulty': points, 'type': 'text', 'question': text,
        'answer': answer, 'aliases': list(aliases), 'fact_id': 'fact:' + identity,
        'event_id': 'event:' + event if event else None, 'event_label': event.replace('_', ' ') if event else None,
        'event_year': year, 'topic_id': 'topic:' + (event or identity),
        'entity_id': entity, 'entity_name': name, 'secondary_entities': [],
        'era': 'unknown' if year is None else 'classic' if year < 1990 else 'golden_era' if year <= 2005 else 'modern_peak' if year <= 2018 else 'contemporary',
        'archetype': archetype, 'mechanic': mechanic, 'tone': tone,
        'template_family': template or archetype + ':' + mechanic,
        'quality_score': .88, 'difficulty_confidence': .72,
        'editorial_note': note or {200: 'شهرة الحدث أو وضوح القرينة يناسب المشجع العادي.', 400: 'يحتاج متابعة منتظمة وربط القرائن.', 600: 'تفصيل معروف عند المتابع القوي أو استنتاج من قرائن محددة.'}[points],
        'source_name': source_name, 'source_url': source_url, 'source_claim': claim,
        'source_checked_at': CHECKED, 'verification_status': 'verified', 'dialect': 'khaleeji',
        'accuracy_pass': True, 'ambiguity_pass': True, 'tolerance_type': 'name_alias',
        **({'visual': visual} if visual else {})}


